fn multiline_scopes_keep_valid_groups_and_expression_diagnostics() {
    for annotation in [
        "File.Write[\n \"/a\"\n , \"/b\"\n ]",
        "File.Write[\n \"/a\",\n \"/b\",\n ]",
        "Http.Connect[\n \"a.example\",\n 443,\n \"b.example\", 80..81,\n ]",
