        let source = format!("{IMPORTS}function sample() -> Unit uses {annotation}\n ()\nend function\n");
        let checked = check(&source);
        assert!(errors(&checked).is_empty(), "{annotation}: {:?}", checked.diagnostics);
    }
    for annotation in [
        "File.Write[\"/a\"\n + \"/b\"]",
        "File.Write[\"/a\" +\n \"/b\"]",
        "File.Write[(\"/a\"\n + \"/b\")]",
    ] {
        let source = format!("{IMPORTS}function sample() -> Unit uses {annotation}\n ()\nend function\n");
        let checked = check(&source);
